<script setup lang="ts">
import {computed,ref} from 'vue'
import {locale,t} from '../../../shared/i18n'
import type {MusicCatalog,MusicPreferences,MusicOption} from '../../works/api/music-settings'
import {toggleMusicOption} from '../../works/model/music-preferences'
const props=defineProps<{modelValue:MusicPreferences;catalog:MusicCatalog;disabled:boolean}>(),emit=defineEmits<{'update:modelValue':[value:MusicPreferences]}>()
const moreGenres=ref(false),advanced=ref(false)
const label=(value:{zh:string;en:string})=>locale.value==='en'?value.en:value.zh
const rows=computed(()=>['genre','emotion','tempo'].map(id=>props.catalog.groups.find(g=>g.id===id)).filter(g=>!!g))
const extras=computed(()=>props.catalog.groups.filter(g=>!['genre','emotion','tempo'].includes(g.id)))
const names:Record<string,string>={genre:'曲风',emotion:'情绪',tempo:'节奏'}
function options(id:string,values:MusicOption[]){return id==='genre'&&!moreGenres.value?values.filter(v=>['pop','folk','rap','chinese'].includes(v.id)||props.modelValue.choices.genre?.includes(v.id)):values}
function choose(group:string,id:string){const value=toggleMusicOption(props.modelValue,props.catalog,group,id);if(value)emit('update:modelValue',value)}
function auto(group:string){emit('update:modelValue',{...props.modelValue,recipeId:null,choices:{...props.modelValue.choices,[group]:[]}})}
function field(key:'vocalGender'|'freeText'|'negativeText',value:string){emit('update:modelValue',{...props.modelValue,recipeId:null,[key]:value} as MusicPreferences)}
</script>
<template><section class="creation-music-choices" :aria-label="t('选定音乐方向')"><div class="creation-direction-heading"><h2><span aria-hidden="true">♫</span> {{ t('选定音乐方向') }}</h2><span>{{ t('音乐方向会影响歌词的表达和节奏') }}</span></div><fieldset :disabled="disabled"><div v-for="group in rows" :key="group.id" class="creation-choice-row"><strong>{{ t(names[group.id]||group.zh) }}</strong><div class="creation-chips"><button type="button" :aria-pressed="!(modelValue.choices[group.id]?.length)" @click="auto(group.id)">{{ t('AI推荐') }}</button><button v-for="option in options(group.id,group.options)" :key="option.id" type="button" :aria-pressed="modelValue.choices[group.id]?.includes(option.id)||false" @click="choose(group.id,option.id)">{{ label(option) }}<span v-if="modelValue.choices[group.id]?.includes(option.id)" aria-hidden="true"> ✓</span></button><button v-if="group.id==='genre'" type="button" :aria-expanded="moreGenres" @click="moreGenres=!moreGenres">{{ t(moreGenres?'收起':'更多') }} <span aria-hidden="true">⌄</span></button></div></div><div class="creation-voice-row"><label>{{ t('演唱声音') }}<select :value="modelValue.vocalGender" @change="field('vocalGender',($event.target as HTMLSelectElement).value)"><option value="AUTO">{{ t('自动') }}</option><option value="MALE">{{ t('男声') }}</option><option value="FEMALE">{{ t('女声') }}</option></select></label><slot name="structure"/></div><button type="button" class="creation-more-toggle" :aria-expanded="advanced" @click="advanced=!advanced"><strong>{{ advanced?'−':'+' }} {{ t('更多音乐设置') }}</strong><span>{{ t('乐器 唱法 编排与排除项') }}</span></button><div v-if="advanced" class="creation-advanced"><div v-for="group in extras" :key="group.id" class="creation-choice-row"><strong>{{ label(group) }}</strong><div class="creation-chips"><button v-for="option in group.options" :key="option.id" type="button" :aria-pressed="modelValue.choices[group.id]?.includes(option.id)||false" @click="choose(group.id,option.id)">{{ label(option) }}</button></div></div><label class="field">{{ t('补充音乐要求') }}<textarea :value="modelValue.freeText" maxlength="300" @input="field('freeText',($event.target as HTMLTextAreaElement).value)"/></label><label class="field">{{ t('需要避开的内容') }}<textarea :value="modelValue.negativeText" maxlength="200" @input="field('negativeText',($event.target as HTMLTextAreaElement).value)"/></label></div></fieldset></section></template>
